#include <stdio.h>
#include <math.h>

int main(void)
{
    double a,b,c,D;
    if (scanf("%lf %lf %lf",&a,&b,&c)!=3) return 1;
    if (a==0) {
        if (b!=0) printf("Linear root = %g\n",-c/b);
        else puts(c==0?"Infinitely many solutions":"No solution");
        return 0;
    }
    D=b*b-4*a*c;
    if (D>0) printf("Roots = %g, %g\n",(-b+sqrt(D))/(2*a),(-b-sqrt(D))/(2*a));
    else if (D==0) printf("Repeated root = %g\n",-b/(2*a));
    else printf("Roots = %g + %gi, %g - %gi\n",-b/(2*a),sqrt(-D)/fabs(2*a),-b/(2*a),sqrt(-D)/fabs(2*a));
    return 0;
}

quadratic.text:
Quadratic roots
Explanation in simple steps
For ax²+bx+c=0, discriminant D=b²−4ac. Positive D gives two real roots, zero D one repeated root, negative D a complex conjugate pair. This introductory calculation assumes moderate finite coefficients; exact zero comparisons are appropriate for the supplied simple examples.


Algorithm
Read a,b,c.
If a=0, handle the linear or degenerate equation.
Compute D.
Use (-b ± sqrt(D))/(2a) for D>=0; otherwise print real part -b/(2a) and imaginary magnitude sqrt(-D)/abs(2a).


C program
#include <stdio.h>
#include <math.h>

int main(void)
{
    double a,b,c,D;
    if (scanf("%lf %lf %lf",&a,&b,&c)!=3) return 1;
    if (a==0) {
        if (b!=0) printf("Linear root = %g\n",-c/b);
        else puts(c==0?"Infinitely many solutions":"No solution");
        return 0;
    }
    D=b*b-4*a*c;
    if (D>0) printf("Roots = %g, %g\n",(-b+sqrt(D))/(2*a),(-b-sqrt(D))/(2*a));
    else if (D==0) printf("Repeated root = %g\n",-b/(2*a));
    else printf("Roots = %g + %gi, %g - %gi\n",-b/(2*a),sqrt(-D)/fabs(2*a),-b/(2*a),sqrt(-D)/fabs(2*a));
    return 0;
}

